-- Goal templates for performance cycles. Idempotent.
--
-- A template is a named set of goals (e.g. "Teller KPIs 2027") that HR assigns to a cycle for a group
-- of employees at once. Each employee gets their own copy in performance_goal, since every copy is
-- scored separately; template_id / template_item_id link the copy back so later edits to the template
-- can reach copies nobody has scored yet.
--
-- Ids are generated by the application (as outofstation_* does), so the same statements run on MySQL.

BEGIN;

CREATE TABLE IF NOT EXISTS performance_goal_template (
  id          BIGINT        PRIMARY KEY,
  name        VARCHAR(150)  NOT NULL,
  description TEXT,
  created_by  BIGINT,
  created_at  TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS performance_goal_template_item (
  id          BIGINT        PRIMARY KEY,
  template_id BIGINT        NOT NULL,
  title       VARCHAR(200)  NOT NULL,
  description TEXT,
  weight      INT,
  target      VARCHAR(300),
  sort_order  INT           NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS performance_goal_template_item_template_idx ON performance_goal_template_item (template_id);

ALTER TABLE performance_goal ADD COLUMN IF NOT EXISTS template_id      BIGINT NULL;
ALTER TABLE performance_goal ADD COLUMN IF NOT EXISTS template_item_id BIGINT NULL;
CREATE INDEX IF NOT EXISTS performance_goal_template_idx ON performance_goal (template_id, cycle_id);

COMMIT;
